// HasVocabularyWith applies the HasEdge predicate on the "vocabulary" edge with a given conditions (other predicates).
func HasVocabularyWith(preds ...predicate.TaxonomyVocabulary) predicate.TaxonomyTermData {
	return predicate.TaxonomyTermData(func(s *sql.Selector) {
		step := newVocabularyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TaxonomyTermData) predicate.TaxonomyTermData {
	return predicate.TaxonomyTermData(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TaxonomyTermData) predicate.TaxonomyTermData {
	return predicate.TaxonomyTermData(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TaxonomyTermData) predicate.TaxonomyTermData {
	return predicate.TaxonomyTermData(sql.NotPredicates(p))
}
